(() => {
  function initMemeInjector() {
    if (!document.body) {
      if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initMemeInjector, { once: true });
      }
      return;
    }

    // Prevent duplicate initialization
    if (window.__agymeme_initialized) return;
    window.__agymeme_initialized = true;

    const MEME_CATALOG = [{"id":"01","name":"元气招手","cat":"开心","emoji":"😄","thumb":"data:image/png;base64,","token":":元气招手:"},{"id":"02","name":"闭眼大笑","cat":"开心","emoji":"😆","thumb":"data:image/png;base64,","token":":闭眼大笑:"},{"id":"03","name":"咧嘴露齿","cat":"开心","emoji":"😁","thumb":"data:image/png;base64,","token":":咧嘴露齿:"},{"id":"04","name":"礼貌微笑","cat":"开心","emoji":"🙂","thumb":"data:image/png;base64,","token":":礼貌微笑:"},{"id":"05","name":"满地打滚","cat":"开心","emoji":"🤣","thumb":"data:image/png;base64,","token":":满地打滚:"},{"id":"06","name":"汗颜苦笑","cat":"日常","emoji":"😅","thumb":"data:image/png;base64,","token":":汗颜苦笑:"},{"id":"07","name":"天使纯良","cat":"可爱","emoji":"😇","thumb":"data:image/png;base64,","token":":天使纯良:"},{"id":"08","name":"单眼眨眼","cat":"开心","emoji":"😉","thumb":"data:image/png;base64,","token":":单眼眨眼:"},{"id":"09","name":"调皮吐舌","cat":"开心","emoji":"😜","thumb":"data:image/png;base64,","token":":调皮吐舌:"},{"id":"10","name":"流口水","cat":"日常","emoji":"🤤","thumb":"data:image/png;base64,","token":":流口水:"},{"id":"11","name":"双眼爱心","cat":"可爱","emoji":"😍","thumb":"data:image/png;base64,","token":":双眼爱心:"},{"id":"12","name":"飞吻比心","cat":"可爱","emoji":"😘","thumb":"data:image/png;base64,","token":":飞吻比心:"},{"id":"13","name":"幸福被宠","cat":"可爱","emoji":"🥰","thumb":"data:image/png;base64,","token":":幸福被宠:"},{"id":"14","name":"从容装酷","cat":"搞怪","emoji":"😎","thumb":"data:image/png;base64,","token":":从容装酷:"},{"id":"15","name":"歪嘴坏笑","cat":"搞怪","emoji":"😏","thumb":"data:image/png;base64,","token":":歪嘴坏笑:"},{"id":"16","name":"面瘫无语","cat":"搞怪","emoji":"😐","thumb":"data:image/png;base64,","token":":面瘫无语:"},{"id":"17","name":"大翻白眼","cat":"搞怪","emoji":"🙄","thumb":"data:image/png;base64,","token":":大翻白眼:"},{"id":"18","name":"斜嘴角纠结","cat":"搞怪","emoji":"🫤","thumb":"data:image/png;base64,","token":":斜嘴角纠结:"},{"id":"19","name":"惊恐倒吸凉气","cat":"生气","emoji":"😨","thumb":"data:image/png;base64,","token":":惊恐倒吸凉气:"},{"id":"20","name":"痛苦抓狂","cat":"生气","emoji":"😫","thumb":"data:image/png;base64,","token":":痛苦抓狂:"},{"id":"21","name":"垂头丧气","cat":"难过","emoji":"😞","thumb":"data:image/png;base64,","token":":垂头丧气:"},{"id":"22","name":"红脸暴怒","cat":"生气","emoji":"😡","thumb":"data:image/png;base64,","token":":红脸暴怒:"},{"id":"23","name":"傲娇喷气","cat":"生气","emoji":"😤","thumb":"data:image/png;base64,","token":":傲娇喷气:"},{"id":"24","name":"嘴巴贴乱码","cat":"生气","emoji":"🤬","thumb":"data:image/png;base64,","token":":嘴巴贴乱码:"},{"id":"25","name":"崩溃大哭","cat":"难过","emoji":"😭","thumb":"data:image/png;base64,","token":":崩溃大哭:"},{"id":"26","name":"软萌委屈","cat":"难过","emoji":"🥺","thumb":"data:image/png;base64,","token":":软萌委屈:"},{"id":"27","name":"含泪微笑","cat":"开心","emoji":"🥲","thumb":"data:image/png;base64,","token":":含泪微笑:"},{"id":"28","name":"休眠待机","cat":"日常","emoji":"😴","thumb":"data:image/png;base64,","token":":休眠待机:"},{"id":"29","name":"大打哈欠","cat":"日常","emoji":"🥱","thumb":"data:image/png;base64,","token":":大打哈欠:"},{"id":"30","name":"震惊呆滞","cat":"日常","emoji":"😱","thumb":"data:image/png;base64,","token":":震惊呆滞:"},{"id":"31","name":"目瞪口呆","cat":"日常","emoji":"😲","thumb":"data:image/png;base64,","token":":目瞪口呆:"},{"id":"32","name":"炸了","cat":"日常","emoji":"🤯","thumb":"data:image/png;base64,","token":":炸了:"},{"id":"33","name":"深度思考","cat":"思考","emoji":"🤔","thumb":"data:image/png;base64,","token":":深度思考:"},{"id":"34","name":"单边挑眉","cat":"思考","emoji":"🤨","thumb":"data:image/png;base64,","token":":单边挑眉:"},{"id":"35","name":"单片眼镜","cat":"思考","emoji":"🧐","thumb":"data:image/png;base64,","token":":单片眼镜:"},{"id":"36","name":"蚊香眼","cat":"日常","emoji":"😵‍💫","thumb":"data:image/png;base64,","token":":蚊香眼:"},{"id":"37","name":"虚线隐身","cat":"日常","emoji":"🫥","thumb":"data:image/png;base64,","token":":虚线隐身:"},{"id":"38","name":"融化一滩","cat":"日常","emoji":"🫠","thumb":"data:image/png;base64,","token":":融化一滩:"},{"id":"39","name":"长叹一口气","cat":"生气","emoji":"😮‍💨","thumb":"data:image/png;base64,","token":":长叹一口气:"},{"id":"40","name":"双眼放星","cat":"开心","emoji":"🤩","thumb":"data:image/png;base64,","token":":双眼放星:"},{"id":"41","name":"双颊爆红","cat":"日常","emoji":"😳","thumb":"data:image/png;base64,","token":":双颊爆红:"},{"id":"42","name":"龇牙咧嘴","cat":"日常","emoji":"😬","thumb":"data:image/png;base64,","token":":龇牙咧嘴:"},{"id":"43","name":"大小眼发癫","cat":"搞怪","emoji":"🤪","thumb":"data:image/png;base64,","token":":大小眼发癫:"},{"id":"44","name":"捂嘴噗嗤","cat":"日常","emoji":"🤭","thumb":"data:image/png;base64,","token":":捂嘴噗嗤:"},{"id":"45","name":"食指抵唇","cat":"日常","emoji":"🤫","thumb":"data:image/png;base64,","token":":食指抵唇:"},{"id":"46","name":"恶心反胃","cat":"搞怪","emoji":"🤮","thumb":"data:image/png;base64,","token":":恶心反胃:"},{"id":"47","name":"见钱眼开","cat":"日常","emoji":"🤑","thumb":"data:image/png;base64,","token":":见钱眼开:"},{"id":"48","name":"欢庆派对","cat":"开心","emoji":"🥳","thumb":"data:image/png;base64,","token":":欢庆派对:"},{"id":"49","name":"微醺恍惚","cat":"日常","emoji":"🥴","thumb":"data:image/png;base64,","token":":微醺恍惚:"},{"id":"50","name":"热到融化","cat":"日常","emoji":"🥵","thumb":"data:image/png;base64,","token":":热到融化:"},{"id":"51","name":"冷到结冰","cat":"日常","emoji":"🥶","thumb":"data:image/png;base64,","token":":冷到结冰:"},{"id":"52","name":"举手敬礼","cat":"日常","emoji":"🫡","thumb":"data:image/png;base64,","token":":举手敬礼:"},{"id":"53","name":"指缝偷看","cat":"日常","emoji":"🫣","thumb":"data:image/png;base64,","token":":指缝偷看:"},{"id":"54","name":"左右狂晃","cat":"日常","emoji":"🫨","thumb":"data:image/png;base64,","token":":左右狂晃:"},{"id":"55","name":"张臂求抱","cat":"可爱","emoji":"🤗","thumb":"data:image/png;base64,","token":":张臂求抱:"},{"id":"56","name":"上下颠倒","cat":"日常","emoji":"🙃","thumb":"data:image/png;base64,","token":":上下颠倒:"},{"id":"57","name":"负伤病号","cat":"难过","emoji":"🤕","thumb":"data:image/png;base64,","token":":负伤病号:"},{"id":"58","name":"摇头摇手","cat":"日常","emoji":"🙂‍↔","thumb":"data:image/png;base64,","token":":摇头摇手:"},{"id":"59","name":"上下点头","cat":"日常","emoji":"🙂‍↕","thumb":"data:image/png;base64,","token":":上下点头:"},{"id":"60","name":"皮诺曹长鼻","cat":"搞怪","emoji":"🤥","thumb":"data:image/png;base64,","token":":皮诺曹长鼻:"},{"id":"61","name":"大胡子假面","cat":"搞怪","emoji":"🥸","thumb":"data:image/png;base64,","token":":大胡子假面:"},{"id":"62","name":"极客学霸","cat":"思考","emoji":"🤓","thumb":"data:image/png;base64,","token":":极客学霸:"},{"id":"63","name":"双子宇航","cat":"思考","emoji":"🧑‍🚀","thumb":"data:image/png;base64,","token":":双子宇航:"},{"id":"64","name":"极光孪星","cat":"思考","emoji":"🌟","thumb":"data:image/png;base64,","token":":极光孪星:"}]
;

    // Fast token-to-image map
    const tokenMap = new Map();
    MEME_CATALOG.forEach(item => {
      if (item.name && item.thumb) {
        tokenMap.set(item.name, item.thumb);
      }
    });

    let activeCat = '全部';
    let searchQuery = '';
    let savedRange = null;

    // Token-to-Image in Chat Bubbles (Auto render stickers in sent user messages)
    const tokenRegex = /:([^\s:<>]+):/g;
    function parseMemeTokensInDOM() {
      const bubbles = document.querySelectorAll('[data-testid="user-message-content"] [data-quotable="true"]');
      bubbles.forEach(b => {
        if (b.dataset.memeParsed) return;
        const text = b.innerText || b.textContent;
        if (tokenRegex.test(text)) {
          b.innerHTML = b.innerHTML.replace(tokenRegex, (match, name) => {
            const thumb = tokenMap.get(name);
            if (thumb) {
              return `<img src="${thumb}" style="width: 54px; height: 54px; object-fit: contain; vertical-align: middle; display: inline-block; margin: -2px 4px 0 2px;" title="${name}" />`;
            }
            return match;
          });
          b.dataset.memeParsed = 'true';
        }
      });
    }

    // Track selection inside composer
    function recordSelection() {
      const sel = window.getSelection();
      const composer = document.querySelector('[contenteditable="true"]');
      if (sel && sel.rangeCount > 0 && composer && composer.contains(sel.anchorNode)) {
        savedRange = sel.getRangeAt(0).cloneRange();
      }
    }

    document.addEventListener('selectionchange', recordSelection);
    document.addEventListener('keyup', recordSelection);
    document.addEventListener('mouseup', recordSelection);

    function insertToken(token) {
      const composer = document.querySelector('[contenteditable="true"]');
      if (!composer) return;
      composer.focus();
      const sel = window.getSelection();
      
      let rangeToUse = null;
      if (savedRange && composer.contains(savedRange.commonAncestorContainer)) {
        rangeToUse = savedRange;
      } else {
        rangeToUse = document.createRange();
        rangeToUse.selectNodeContents(composer);
        rangeToUse.collapse(false);
      }
      sel.removeAllRanges();
      sel.addRange(rangeToUse);

      document.execCommand('insertText', false, ' ' + token + ' ');
      if (sel.rangeCount > 0) {
        savedRange = sel.getRangeAt(0).cloneRange();
      }
      composer.dispatchEvent(new Event('input', { bubbles: true }));
      showToast('已插入 ' + token + ' ✨');
    }

    function showToast(msg) {
      let toast = document.getElementById('agy-meme-toast');
      if (!toast) {
        toast = document.createElement('div');
        toast.id = 'agy-meme-toast';
        toast.style.cssText = 'position:fixed;bottom:85px;left:50%;transform:translateX(-50%);background:rgba(24,24,27,0.95);color:#fff;padding:8px 18px;border-radius:24px;font-size:13px;font-weight:500;z-index:1000001;pointer-events:none;transition:all 0.25s cubic-bezier(0.16, 1, 0.3, 1);box-shadow:0 8px 30px rgba(0,0,0,0.5);border:1px solid rgba(255,255,255,0.15);opacity:0;transform:translate(-50%, 10px);';
        document.body.appendChild(toast);
      }
      toast.innerText = msg;
      toast.style.opacity = '1';
      toast.style.transform = 'translate(-50%, 0)';
      clearTimeout(toast._timer);
      toast._timer = setTimeout(() => {
        toast.style.opacity = '0';
        toast.style.transform = 'translate(-50%, 10px)';
      }, 1600);
    }

    // Create Popup Modal
    let popup = document.getElementById('agy-meme-popup');
    if (!popup) {
      popup = document.createElement('div');
      popup.id = 'agy-meme-popup';
      popup.style.cssText = [
        'position: fixed',
        'bottom: 74px',
        'left: 20px',
        'width: 480px',
        'max-width: 92vw',
        'height: 490px',
        'background: #18181b',
        'border: 1px solid rgba(255, 255, 255, 0.12)',
        'border-radius: 14px',
        'box-shadow: 0 20px 50px rgba(0, 0, 0, 0.7)',
        'z-index: 1000000',
        'display: none',
        'flex-direction: column',
        'overflow: hidden',
        'font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
        'color: #f4f4f5',
        'user-select: none'
      ].join(';');

      // Prevent clicks inside popup from bubbling to document (prevents accidental closing)
      popup.addEventListener('click', (e) => {
        e.stopPropagation();
      });
      popup.addEventListener('mousedown', (e) => {
        e.stopPropagation();
      });

      popup.innerHTML = `
        <div style="padding: 12px 14px 10px; border-bottom: 1px solid rgba(255,255,255,0.08); display: flex; flex-direction: column; gap: 8px;">
          <div style="display: flex; align-items: center; justify-content: space-between; gap: 8px;">
            <div style="position: relative; flex: 1;">
              <input id="agy-meme-search" type="text" placeholder="搜索描述 / 关键词..." style="width: 100%; box-sizing: border-box; background: rgba(255,255,255,0.06); border: 1px solid rgba(255,255,255,0.12); border-radius: 8px; padding: 6px 12px; font-size: 13px; color: #fff; outline: none; transition: border-color 0.2s;" />
            </div>
            <button id="agy-meme-clear" type="button" style="background: transparent; border: none; color: #a1a1aa; font-size: 12px; cursor: pointer; padding: 4px 8px; border-radius: 6px; transition: color 0.15s;">清空</button>
            <div id="agy-meme-count" style="font-size: 11px; color: #a1a1aa; background: rgba(255,255,255,0.06); padding: 4px 10px; border-radius: 20px; white-space: nowrap;">共 64 张</div>
          </div>
          <div style="display: flex; gap: 6px; align-items: center; overflow-x: auto; padding-bottom: 2px;">
            <span style="font-size: 11px; color: #71717a; white-space: nowrap;">情绪:</span>
            <div id="agy-meme-cats" style="display: flex; gap: 6px;"></div>
          </div>
        </div>
        <div id="agy-meme-grid" style="flex: 1; overflow-y: auto; padding: 12px; display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px;"></div>
      `;

      document.body.appendChild(popup);

      const searchInput = popup.querySelector('#agy-meme-search');
      const clearBtn = popup.querySelector('#agy-meme-clear');
      const countBadge = popup.querySelector('#agy-meme-count');
      const catsContainer = popup.querySelector('#agy-meme-cats');
      const grid = popup.querySelector('#agy-meme-grid');

      searchInput.oninput = (e) => {
        searchQuery = e.target.value.trim().toLowerCase();
        renderGrid();
      };

      searchInput.onfocus = () => { searchInput.style.borderColor = '#3b82f6'; };
      searchInput.onblur = () => { searchInput.style.borderColor = 'rgba(255,255,255,0.12)'; };

      clearBtn.onclick = (e) => {
        if (e) {
          e.preventDefault();
          e.stopPropagation();
        }
        searchInput.value = '';
        searchQuery = '';
        activeCat = '全部';
        renderCats();
        renderGrid();
      };

      const categories = ['全部', '开心', '日常', '可爱', '思考', '难过', '生气', '搞怪'];

      function renderCats() {
        catsContainer.innerHTML = '';
        categories.forEach(cat => {
          const pill = document.createElement('button');
          pill.type = 'button';
          pill.innerText = cat;
          const isActive = activeCat === cat;
          pill.style.cssText = [
            'border: none',
            'padding: 3px 10px',
            'border-radius: 12px',
            'font-size: 11px',
            'cursor: pointer',
            'white-space: nowrap',
            'transition: all 0.15s',
            'background: ' + (isActive ? '#3b82f6' : 'rgba(255,255,255,0.06)'),
            'color: ' + (isActive ? '#ffffff' : '#a1a1aa'),
            'font-weight: ' + (isActive ? '600' : '400')
          ].join(';');
          
          pill.onclick = (e) => {
            e.preventDefault();
            e.stopPropagation();
            activeCat = cat;
            renderCats();
            renderGrid();
          };
          catsContainer.appendChild(pill);
        });
      }

      function renderGrid() {
        grid.innerHTML = '';
        const filtered = MEME_CATALOG.filter(item => {
          const matchCat = activeCat === '全部' || item.cat === activeCat;
          const matchSearch = !searchQuery || item.name.toLowerCase().includes(searchQuery) || item.emoji.includes(searchQuery);
          return matchCat && matchSearch;
        });

        countBadge.innerText = '共 ' + filtered.length + ' 张';

        if (filtered.length === 0) {
          grid.innerHTML = '<div style="grid-column: 1 / -1; text-align: center; color: #71717a; padding: 40px 0; font-size: 13px;">没有找到匹配的表情包 🐱</div>';
          return;
        }

        filtered.forEach(item => {
          const card = document.createElement('div');
          card.style.cssText = [
            'background: rgba(255, 255, 255, 0.03)',
            'border: 1px solid rgba(255, 255, 255, 0.06)',
            'border-radius: 10px',
            'padding: 8px 4px 6px',
            'display: flex',
            'flex-direction: column',
            'align-items: center',
            'justify-content: center',
            'cursor: pointer',
            'transition: all 0.18s ease-out'
          ].join(';');
          card.title = item.name + ' (' + item.token + ')';

          card.onmouseenter = () => {
            card.style.background = 'rgba(255, 255, 255, 0.1)';
            card.style.transform = 'translateY(-3px)';
            card.style.borderColor = 'rgba(255, 255, 255, 0.2)';
          };
          card.onmouseleave = () => {
            card.style.background = 'rgba(255, 255, 255, 0.03)';
            card.style.transform = 'translateY(0)';
            card.style.borderColor = 'rgba(255, 255, 255, 0.06)';
          };

          card.onclick = (e) => {
            e.preventDefault();
            e.stopPropagation();
            insertToken(item.token);
            popup.style.display = 'none';
          };

          const img = document.createElement('img');
          img.src = item.thumb;
          img.style.cssText = 'width: 72px; height: 72px; object-fit: contain; pointer-events: none;';
          img.loading = 'lazy';

          const label = document.createElement('span');
          label.innerText = item.name;
          label.style.cssText = 'font-size: 11px; color: #d4d4d8; margin-top: 6px; max-width: 90%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; pointer-events: none;';

          card.appendChild(img);
          card.appendChild(label);
          grid.appendChild(card);
        });
      }

      renderCats();
      renderGrid();

      // Close when clicking outside (originating truly outside popup and button)
      document.addEventListener('click', (e) => {
        if (popup.style.display === 'flex' && !popup.contains(e.target) && !e.target.closest('#agy-meme-composer-btn')) {
          popup.style.display = 'none';
        }
      });

      document.addEventListener('keydown', (e) => {
        if (e.key === 'Escape' && popup.style.display === 'flex') {
          popup.style.display = 'none';
        }
      });
    }

    // Inject Button into Composer Footer
    function injectBtn() {
      if (document.getElementById('agy-meme-composer-btn')) return;
      const footer = document.querySelector('.agy-composer-footer > div.flex.items-center') || document.querySelector('.agy-composer-footer');
      if (!footer) return;

      const btn = document.createElement('button');
      btn.id = 'agy-meme-composer-btn';
      btn.type = 'button';
      btn.setAttribute('aria-label', '选择表情包 (AGY Meme)');
      btn.setAttribute('title', '选择表情包 (AGY Meme)');
      btn.className = 'p-1.5 rounded-full text-secondary-foreground hover:bg-secondary cursor-pointer flex items-center justify-center transition-colors';
      btn.style.width = '28px';
      btn.style.height = '28px';
      btn.style.margin = '0 2px';
      btn.innerHTML = `<svg xmlns="http://www.w3.org/2000/svg" width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><path d="M8 14s1.5 2 4 2 4-2 4-2"></path><line x1="9" y1="9" x2="9.01" y2="9"></line><line x1="15" y1="9" x2="15.01" y2="9"></line></svg>`;

      btn.onclick = (e) => {
        e.preventDefault();
        e.stopPropagation();
        const p = document.getElementById('agy-meme-popup');
        if (!p) return;
        const isVisible = p.style.display === 'flex';
        if (isVisible) {
          p.style.display = 'none';
        } else {
          const rect = btn.getBoundingClientRect();
          p.style.bottom = (window.innerHeight - rect.top + 8) + 'px';
          p.style.left = Math.max(12, Math.min(rect.left, window.innerWidth - 500)) + 'px';
          p.style.display = 'flex';
          const si = p.querySelector('#agy-meme-search');
          if (si) si.focus();
        }
      };

      const plusBtn = footer.querySelector('button[aria-label="Add context"]') || footer.firstElementChild;
      if (plusBtn && plusBtn.nextSibling) {
        footer.insertBefore(btn, plusBtn.nextSibling);
      } else {
        footer.appendChild(btn);
      }
    }

    injectBtn();
    parseMemeTokensInDOM();

    const observer = new MutationObserver(() => {
      injectBtn();
      parseMemeTokensInDOM();
    });
    observer.observe(document.body, { childList: true, subtree: true });
  }

  // Safe startup hook
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initMemeInjector, { once: true });
  } else {
    initMemeInjector();
  }
})()
